const q=s=>document.querySelector(s),ctx=[...document.querySelectorAll('canvas')].map(c=>c.getContext('2d'));
let t=0,playing=false,last=0,wait=0,freeze=0,contact=false,registration,ready=false,audio;
const original=new Image(),heroes=Array.from({length:16},()=>new Image()),flames=Array.from({length:12},()=>new Image());
