Promise.all([imageLoad(original,'assets/flame-sequence.png'),...heroes.map((im,i)=>imageLoad(im,'assets/hero-only/frames/frame-'+String(i).padStart(2,'0')+'.png')),...flames.map((im,i)=>imageLoad(im,'assets/flame-fx/frames/frame-'+String(i).padStart(2,'0')+'.png')),fetch('assets/hero-only/registration.json').then(r=>{if(!r.ok)throw Error('registration');return r.json()}).then(r=>registration=r)]).then(()=>{ready=true;document.querySelectorAll('button').forEach(b=>b.disabled=false);draw()}).catch(()=>{q('#clock').textContent='素材載入失敗，請重新整理';q('#clock').className='error'});
