function find(time,arr){for(let i=0;i<arr.length-1;i++)if(time<arr[i+1])return i;return arr.length-2}
function floor(x){const g=x.createLinearGradient(0,0,0,440);g.addColorStop(0,'#1a3039');g.addColorStop(1,'#304941');x.fillStyle=g;x.fillRect(0,0,800,440);x.fillStyle='#2c444a';for(let i=0;i<7;i++){x.fillRect(20+i*130,165,11,145);x.fillRect(14+i*130,160,23,8)}x.strokeStyle='#a5aa7e33';for(let yy=340;yy<440;yy+=23){x.beginPath();x.moveTo(0,yy);x.lineTo(800,yy);x.stroke()}for(let i=0;i<12;i++){x.beginPath();x.moveTo(400+(i-6)*45,340);x.lineTo(400+(i-6)*100,440);x.stroke()}}
function enemies(){const center=+q('#distance').value;return q('#count').value==='3'?[center-90,center-35,center+20]:[center]}
function golem(x,pos,index){const age=t-(1.1+index*.06),react=q('#feedback').checked&&age>=0,amp=react?Math.exp(-age*5)*Math.sin(Math.min(age*13,Math.PI)):0;const sh=original.naturalHeight/4;x.save();x.translate(pos+amp*18,365+index*6);x.rotate(amp*.16);x.fillStyle='#0e1b2355';x.beginPath();x.ellipse(0,0,48,11,0,0,7);x.fill();x.drawImage(original,245,0,198,sh,-130,-310,260,310);if(react&&age<.08){x.globalCompositeOperation='screen';x.globalAlpha=.48*(1-age/.08);x.fillStyle='#ffe6a1';x.beginPath();x.ellipse(0,-100,45,78,0,0,7);x.fill()}x.restore();if(react&&age<.85){x.save();x.globalAlpha=1-age/.85;x.fillStyle='#ffe0a0';x.font='bold 22px system-ui';x.fillText('328',pos-20,130-age*22);for(let k=0;k<12;k++){const a=k*2.39996,r=(60+k*6)*age;x.fillStyle=k%2?'#ff9b35':'#fff1b0';x.fillRect(pos+Math.cos(a)*r,250+Math.sin(a)*r+age*age*40,3,3)}x.restore()}}
function draw(){if(!ready)return;let i=find(Math.min(t,3.199),ab);ctx.forEach((x,n)=>{x.setTransform(1,0,0,1,0,0);x.clearRect(0,0,800,440);x.save();if(n===1&&q('#feedback').checked){const age=t-1.1,shake=age>=0?4*Math.exp(-age*11):0;x.translate(Math.sin(age*70)*shake,Math.sin(age*97)*shake*.6)}floor(x);if(n===0){const sw=original.naturalWidth/4,sh=original.naturalHeight/4;x.drawImage(original,(i%4)*sw,Math.floor(i/4)*sh,sw,sh,25,-5,750,375)}else{const reg=registration.items[i],scale=1.17,baseX=150,baseY=365;const dx=baseX-reg.rootX*scale,dy=baseY-reg.feet*scale,tip={x:dx+reg.tip[0]*scale,y:dy+reg.tip[1]*scale};const positions=enemies();if(q('#enemy').checked)positions.forEach((p,j)=>golem(x,p,j));if(q('#hero').checked){x.fillStyle='#101e2455';x.beginPath();x.ellipse(baseX,baseY,58,11,0,0,7);x.fill();x.drawImage(heroes[i],dx,dy,heroes[i].naturalWidth*scale,heroes[i].naturalHeight*scale)}if(q('#effect').checked&&t>=fb[0]&&t<fb[12]){const f=find(t,fb),end={x:positions.at(-1)-8,y:267},deltaX=end.x-tip.x,deltaY=end.y-tip.y,length=Math.hypot(deltaX,deltaY);x.save();x.translate(tip.x,tip.y);x.rotate(Math.atan2(deltaY,deltaX));x.scale(length/365,.72);x.drawImage(flames[f],-90,-190);x.restore()}}
x.restore();x.fillStyle='#afc4bf';x.font='12px system-ui';x.fillText(t.toFixed(2)+'s',15,26)});q('#scrub').value=t*1000;q('#clock').textContent=t.toFixed(2)+' / 3.40 秒';q('#play').textContent=playing?'暫停':'同步播放';q('#status').textContent=t<.74?'蓄力 · 抬杖聚焰':t<1.1?'噴發 · 推杖釋放':t<1.85?'命中 · 焰流與敵人反應':'消散 · 煙塵與收招';q('#distance-label').textContent=+q('#distance').value<540?'近距':+q('#distance').value>640?'遠距':'中距'}
function sfx(){if(!q('#sound').checked)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const now=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.setValueAtTime(180,now);o.frequency.exponentialRampToValueAtTime(35,now+.22);g.gain.setValueAtTime(.09,now);g.gain.exponentialRampToValueAtTime(.001,now+.3);o.connect(g);g.connect(audio.destination);o.start();o.stop(now+.32)}catch{}}
function reset(){t=wait=freeze=0;contact=false;draw()}
q('#play').onclick=()=>{if(t>=3.4)reset();playing=!playing;draw()};q('#reset').onclick=()=>{reset();playing=true;draw()};q('#step').onclick=()=>{playing=false;t=Math.min(3.4,t+.13);freeze=0;contact=t>=1.1;draw()};q('#scrub').oninput=()=>{playing=false;t=+q('#scrub').value/1000;freeze=0;contact=t>=1.1;draw()};document.querySelectorAll('.options input,.options select').forEach(el=>el.addEventListener('input',draw));
function tick(now){const dt=Math.min((now-last)/1000||0,.05);last=now;if(ready&&playing){if(freeze>0)freeze=Math.max(0,freeze-dt);else if(t<3.4){t=Math.min(3.4,t+dt*(+q('#speed').value));if(!contact&&t>=1.1){contact=true;if(q('#feedback').checked){t=1.1;freeze=.08}sfx()}}else if(q('#loop').checked){wait+=dt;if(wait>.7)reset()}else playing=false;draw()}requestAnimationFrame(tick)}requestAnimationFrame(tick);
